        const error = err instanceof AxiError
            ? err
            : new AxiError(err instanceof Error ? err.message : 'Failed to retrieve bootloader', 'VALIDATION_ERROR', ['Use a skill name containing only letters, numbers, dots, underscores, or hyphens']);
